/**
 * Neo Test (testing agent studio) client tool.
 *
 * The agent drives `/testing` through this one tool, the same way Neo Synth
 * drives `/synth`. The agent reads the code (and KT docs), records the
 * stack, proposes a plan and writes tests; the studio runs the plan with its
 * own harness, parses the artifacts, evaluates the quality gates and writes
 * the report. Numbers in receipts come from the studio, never the agent.
 */

export const TEST_CONTROL_TOOL_NAME = "test_control";

/** Action discriminator generated by the SDK for a client-defined tool. */
export const TEST_CONTROL_ACTION_KIND =
  `ClientAction_${TEST_CONTROL_TOOL_NAME}` as const;

/**
 * Prefix on every receipt posted back into the conversation after a command
 * ran in the browser (and on user answers to choice cards). Hidden from the
 * transcript by `isTestReceiptEvent`.
 */
export const TEST_RESULT_PREFIX = "[neotest result] ";

/**
 * Commands the agent may issue. The complete set ships at once: the
 * agent-server caches a client tool's schema per tool NAME for its whole
 * life (see `src/constants/onboarding-control.ts`). Per-command payload
 * shapes are answered by `describe`, never encoded in the schema.
 */
export const TEST_CONTROL_COMMANDS = [
  // Orientation: project, stack, plan, gates, runs, findings, KT docs,
  // Synth datasets, payload shapes.
  "describe",
  // Languages, frameworks, runners, commands and existing suites found.
  "record_stack",
  // The suites to run, per kind, with commands and result files.
  "set_plan",
  // Thresholds the report is judged against (before the first run).
  "set_gates",
  // A question rendered as selectable cards; the user's choice comes back as
  // a receipt the agent must wait for.
  "ask_choice",
  // The studio runs the named suites with the harness and parses results.
  "run",
  // Mutation proof: the studio mutates one file and runs a suite.
  "prove",
  // A bug or risk the tests exposed, with evidence.
  "record_finding",
  // A line in the live log (no receipt).
  "log",
  // Final summary; refused until the plan ran and the report exists.
  "complete",
] as const;

export type TestControlCommand = (typeof TEST_CONTROL_COMMANDS)[number];

export const TEST_PROJECT_STATUSES = [
  "intake",
  "discovering",
  "planning",
  "ready",
  "running",
  "reporting",
  "done",
  "failed",
] as const;
export type TestProjectStatus = (typeof TEST_PROJECT_STATUSES)[number];
